const lin=(a,b)=>Pl([a,'x'],[b,'']);
const Ps=x=>x<0?`(${n(x)})`:n(x);
const sq2=p=>`${par(p)}²`;
const pr=(...fs)=>prodStr(fs);
const g3=(a,b,c)=>gcd(gcd(a,b),c);
const tau=k=>{k=Math.abs(k);let c=0;for(let d=1;d<=k;d++)if(k%d===0)c++;return c;};
const isPrime=v=>{if(v<2)return false;for(let d=2;d*d<=v;d++)if(v%d===0)return false;return true;};
const sgn=v=>v<0?'−':'+';

/* ---------- theory ---------- */
const theory=[
{title:'Что значит «разложить на множители»',lvl:0,html:`
<p class="hook">⚡ Спорим, ты посчитаешь ${M('2026² − 2024²')} за три секунды, без калькулятора? Ответ — 8100. Секрет: ${M('2026² − 2024² = (2026 − 2024)(2026 + 2024) = 2 · 4050')}. Это и есть <b>разложение на множители</b> — превращение суммы в произведение. Сегодня научишься пяти способам, а в конце — трюкам, которыми решают олимпиадные задачи.</p>
<div class="box rule"><b>Определение</b><b>Разложить многочлен на множители</b> — представить его в виде <b>произведения</b> нескольких многочленов (или одночлена и многочлена).<br>Это действие, <b>обратное</b> раскрытию скобок: ${M('2x(x + 3) → 2x² + 6x')} — раскрыли; ${M('2x² + 6x → 2x(x + 3)')} — разложили.</div>
<p><b>Зачем?</b> Произведение удобнее суммы: его легко приравнять к нулю (решить уравнение), сократить в дроби, оценить знак, посчитать в уме.</p>
<h3>Способ 1: вынесение общего множителя</h3>
<div class="box rule"><b>Правило</b>Общий множитель: <b>НОД коэффициентов</b> и <b>каждая общая буква в наименьшей степени</b>. Каждый член делим на него — частные пишем в скобках.</div>
<div class="box ex"><b>Пример</b>${M('12x³y − 18x²y²')}: НОД(12, 18) = 6; x — в наименьшей степени x², y — в степени 1. Общий множитель ${M('6x²y')}.<br>${M('12x³y : 6x²y = 2x')}, ${M('18x²y² : 6x²y = 3y')} → ${M('6x²y(2x − 3y)')}.</div>
<div class="box err"><b>Частые ошибки</b>• Потерять единицу: ${M('4x² + 2x = 2x(2x)')} — нет! ${M('2x : 2x = 1')}, ответ ${M('2x(2x + 1)')}.<br>• Вынести не всё: ${M('6x³ − 9x² = 3x(2x² − 3x)')} — в скобке ещё остался общий x. Наибольший общий множитель — ${M('3x²')}.</div>
<div class="box tip"><b>Проверка</b>Раскрой скобки обратно — должен получиться исходный многочлен.</div>`},
{title:'Общая скобка и смена знака',lvl:1,html:`
<div class="box rule"><b>Правило</b>Общим множителем может быть целая <b>скобка</b>: ${M('3x(a − b) + 5(a − b) = (a − b)(3x + 5)')}.<br>Полезное тождество: ${M('b − a = −(a − b)')}.</div>
<p><b>Почему?</b> Обозначь скобку одной буквой: ${M('a − b = t')}. Тогда ${M('3x·t + 5·t = t(3x + 5)')} — обычное вынесение.</p>
<div class="box ex"><b>Пример со сменой знака</b>${M('2x(a − b) + 7y(b − a) = 2x(a − b) − 7y(a − b) = (a − b)(2x − 7y)')}.</div>
<div class="box ex"><b>Считаем в уме</b>${M('37 · 73 + 37 · 27 = 37 · (73 + 27) = 37 · 100 = 3700')}.</div>
<div class="box err"><b>Ловушка</b>${M('(b − a)')} и ${M('(a − b)')} — <b>не</b> одинаковые скобки! Они отличаются знаком. Прежде чем выносить, сделай их одинаковыми, вынеся минус.</div>`},
{title:'Способ 2: группировка',lvl:2,html:`
<div class="box rule"><b>Правило</b>1) Разбей члены на группы. 2) В каждой группе вынеси общий множитель. 3) Если в скобках получилось одно и то же — вынеси эту скобку.</div>
<div class="box ex"><b>Пример</b>${M('x³ + 3x² + 2x + 6 = x²(x + 3) + 2(x + 3) = (x + 3)(x² + 2)')}.</div>
<div class="box ex"><b>Пример с двумя парами букв</b>${M('ax − ay + 2bx − 2by = a(x − y) + 2b(x − y) = (x − y)(a + 2b)')}.</div>
<p><b>Как выбрать группы?</b> Пробуй объединить члены с общими множителями. Если скобки не совпали — перегруппируй или вынеси из второй группы минус.</p>
<div class="box err"><b>Ловушка</b>${M('x³ + 3x² − 2x − 6 = x²(x + 3) − 2x − 6')} — и застряли? Из второй группы выноси <b>−2</b>: ${M('−2(x + 3)')}. Тогда ${M('(x + 3)(x² − 2)')}.</div>`},
{title:'Способ 3: формулы сокращённого умножения',lvl:3,html:`
<div class="box rule"><b>Формулы «справа налево»</b>${M('a² − b² = (a − b)(a + b)')}<br>${M('a² + 2ab + b² = (a + b)²')}<br>${M('a² − 2ab + b² = (a − b)²')}</div>
<p><b>Как узнать полный квадрат?</b> Два члена — квадраты (${M('a²')} и ${M('b²')}), а третий — <b>удвоенное</b> произведение ${M('2ab')}. ${M('9x² − 12x + 4')}: ${M('9x² = (3x)²')}, ${M('4 = 2²')}, ${M('2·3x·2 = 12x')} ✅ → ${M('(3x − 2)²')}.</p>
<div class="box ex"><b>Примеры</b>${M('49x² − 25 = (7x − 5)(7x + 5)')}<br>${M('x² + 10x + 25 = (x + 5)²')}<br>${M('57² − 43² = 14 · 100 = 1400')}</div>
<div class="box err"><b>Ловушки</b>• ${M('a² + b²')} на множители <b>не</b> раскладывается (в школьных числах).<br>• ${M('x² + 3x + 9')} — не полный квадрат: нужно было бы ${M('6x')}.<br>• ${M('(5 − 7x)(5 + 7x)')} — это ${M('25 − 49x²')}, а не ${M('49x² − 25')}: порядок в «минус»-скобке важен.</div>`},
{title:'Сумма и разность кубов',lvl:4,html:`
<div class="box rule"><b>Формулы</b>${M('a³ − b³ = (a − b)(a² + ab + b²)')}<br>${M('a³ + b³ = (a + b)(a² − ab + b²)')}<br>${M('a³ ± 3a²b + 3ab² ± b³ = (a ± b)³')}</div>
<p>Вторая скобка — <b>неполный квадрат</b>: в середине просто ${M('ab')}, а не ${M('2ab')}. Знак в середине — противоположный знаку в первой скобке.</p>
<div class="box ex"><b>Примеры</b>${M('8x³ − 27 = (2x)³ − 3³ = (2x − 3)(4x² + 6x + 9)')}<br>${M('x³ + 64 = (x + 4)(x² − 4x + 16)')}<br>${M('x³ + 6x² + 12x + 8 = (x + 2)³')}</div>
<div class="box err"><b>Частые ошибки</b>• ${M('a³ − b³ = (a − b)³')} — нет! ${M('(a − b)³')} содержит ещё ${M('−3a²b + 3ab²')}.<br>• Поставить ${M('2ab')} в неполный квадрат.<br>• Перепутать знак среднего члена.</div>
<div class="box tip"><b>Запоминалка</b>«Первая скобка — как в условии, во второй — квадрат, минус-произведение-наоборот, квадрат».</div>`},
{title:'Комбинируем способы',lvl:5,html:`
<div class="box rule"><b>Порядок действий</b>1) Есть общий множитель? <b>Вынеси</b>.<br>2) Посмотри на скобку: формула? <b>Примени</b>.<br>3) Четыре и больше членов? Попробуй <b>группировку</b>.<br>4) Проверь каждую скобку: может, она раскладывается дальше?</div>
<div class="box ex"><b>Пример</b>${M('2x³ − 18x = 2x(x² − 9) = 2x(x − 3)(x + 3)')}.</div>
<div class="box ex"><b>Пример</b>${M('x⁴ − 16 = (x² − 4)(x² + 4) = (x − 2)(x + 2)(x² + 4)')}.</div>
<div class="box ex"><b>Пример</b>${M('x² − 6x + 9 − y² = (x − 3)² − y² = (x − 3 − y)(x − 3 + y)')} — группировка + две формулы.</div>
<div class="box err"><b>Ловушка: остановиться на полпути</b>${M('2x(x² − 9)')} — ещё <b>не</b> до конца. Скобка ${M('x² − 9')} раскладывается. «Разложи на множители» в задачах означает «до конца».</div>`},
{title:'Выделение полного квадрата',lvl:6,html:`
<div class="box rule"><b>Правило</b>${M('x² + 2kx = (x + k)² − k²')}. Значит, ${M('x² + bx + c = (x + b/2)² + (c − b²/4)')}.</div>
<p><b>Почему?</b> ${M('(x + k)² = x² + 2kx + k²')} — лишнее ${M('k²')} вычитаем. Как в магазине: «квадрат» продают только целиком, поэтому докупаем ${M('k²')}, а потом его же отдаём обратно.</p>
<div class="box ex"><b>Пример</b>${M('x² − 6x + 13 = (x² − 6x + 9) + 4 = (x − 3)² + 4')}.<br>Отсюда сразу видно: ${M('(x − 3)² ≥ 0')}, значит выражение <b>≥ 4</b>, а наименьшее значение 4 достигается при x = 3.</div>
<div class="box ex"><b>Разложение через полный квадрат</b>${M('x² − 6x + 5 = (x − 3)² − 4 = (x − 3 − 2)(x − 3 + 2) = (x − 5)(x − 1)')}.</div>
<div class="box err"><b>Ловушка</b>Взять k = b, а не b/2: ${M('x² − 6x = (x − 6)² − 36')} — неверно. Удвоенное произведение 2kx = 6x → k = 3.</div>`},
{title:'Трёхчлен x² + px + q подбором',lvl:7,html:`
<div class="box rule"><b>Правило</b>${M('(x + m)(x + n) = x² + (m + n)x + mn')}. Чтобы разложить ${M('x² + px + q')}, ищи два числа: <b>произведение = q</b>, <b>сумма = p</b>.</div>
<div class="box ex"><b>Пример</b>${M('x² + 7x + 12')}: пары с произведением 12: 1·12, 2·6, <b>3·4</b> — сумма 7 ✅. Ответ: ${M('(x + 3)(x + 4)')}.<br>${M('x² − x − 12')}: произведение −12, сумма −1 → 3 и −4: ${M('(x + 3)(x − 4)')}.</div>
<div class="box tip"><b>Подсказки по знакам</b>q > 0 — числа одного знака (знак как у p). q < 0 — разных знаков, больший по модулю — со знаком p.</div>
<p><b>Поиграй:</b> выбери p и q — тренажёр переберёт все пары за тебя.</p>
<div class="widget" id="w-pq"></div>
<div class="box ex"><b>Если старший коэффициент не 1</b>${M('2x² + 7x + 3')}: разобьём средний член так, чтобы работала группировка (числа с произведением 2·3 = 6 и суммой 7 — это 1 и 6): ${M('2x² + x + 6x + 3 = x(2x + 1) + 3(2x + 1) = (2x + 1)(x + 3)')}.</div>`},
{title:'Применение: уравнения и вычисления',lvl:8,html:`
<div class="box rule"><b>Главное свойство</b>Произведение равно нулю ⇔ <b>хотя бы один</b> множитель равен нулю.</div>
<div class="box ex"><b>Уравнение</b>${M('x³ − 9x = 0')} → ${M('x(x − 3)(x + 3) = 0')} → x = 0, x = 3, x = −3.</div>
<div class="box err"><b>Ловушка</b>Разделить ${M('x³ = 9x')} на x — потеряешь корень 0. Не дели на выражение с переменной, раскладывай!</div>
<div class="box ex"><b>Вычисления</b>${M('2026² − 2025 · 2027 = 2026² − (2026 − 1)(2026 + 1) = 2026² − 2026² + 1 = 1')}.<br>${M('47² − 2·47·37 + 37² = (47 − 37)² = 100')}.</div>
<div class="fact">На трудности разложения на множители держится шифрование RSA, которым защищены банковские переводы: перемножить два огромных простых числа компьютер может мгновенно, а разложить их произведение обратно — нет.</div>`},
{title:'★ Олимпиадные приёмы',lvl:9,html:`
<div class="box rule"><b>Тождество Софи Жермен</b>${M('a⁴ + 4b⁴ = (a² + 2b²)² − (2ab)² = (a² − 2ab + 2b²)(a² + 2ab + 2b²)')}.<br>Отсюда: ${M('n⁴ + 4 = (n² − 2n + 2)(n² + 2n + 2)')}. При n > 1 оба множителя больше 1, значит ${M('n⁴ + 4')} — <b>составное</b>. Простое только при n = 1: ${M('1 + 4 = 5')}.</div>
<div class="box rule"><b>Сумма трёх кубов</b>${M('x³ + y³ + z³ − 3xyz = (x + y + z)(x² + y² + z² − xy − yz − zx)')}.<br>Следствие: если ${M('x + y + z = 0')}, то ${M('x³ + y³ + z³ = 3xyz')}.</div>
<div class="box rule"><b>Уравнения в целых числах</b>${M('xy + x + y = 11')} → прибавим 1: ${M('xy + x + y + 1 = 12')} → ${M('(x + 1)(y + 1) = 12')}. Теперь перебираем делители 12!</div>
<div class="box rule"><b>Делимость</b>${M('n³ − n = (n − 1)n(n + 1)')} — три подряд идущих числа: среди них есть чётное и кратное 3. Значит, ${M('n³ − n')} всегда делится на 6.</div>
<div class="fact">Софи Жермен (1776–1831) — французский математик. Женщин тогда не пускали в университеты, и она переписывалась с великим Гауссом под мужским именем «месье Лёблан». Гаусс узнал правду через несколько лет — и восхитился ещё больше.</div>`},
{title:'Шпаргалка',html:`
<ul class="steps"><li>Вынеси общий множитель (НОД + буквы в наименьшей степени).</li>
<li>Формулы: ${M('a² − b²')}, ${M('(a ± b)²')}, ${M('a³ ± b³')}.</li>
<li>4 члена — группировка. ${M('b − a = −(a − b)')}.</li>
<li>${M('x² + px + q = (x + m)(x + n)')}: m + n = p, mn = q.</li>
<li>${M('x² + 2kx = (x + k)² − k²')}.</li>
<li>Раскладывай до конца и проверяй раскрытием скобок.</li></ul>`}
];

